settings.liquid:
{% if product.tags contains 'no-usa-ship' %}
  <div style="border: 1px solid #7d1f2c; color: #7d1f2c; padding: 12px 16px; border-radius: 4px; margin: 15px 0; font-size: 14px; line-height: 1.4; text-align: center;">
    {% if request.locale.iso_code == 'it' %}
      A causa di restrizioni doganali, al momento <strong>non è possibile spedire</strong> questo prodotto negli <strong>STATI UNITI</strong>. Di conseguenza, l'intero ordine che lo contiene verrà annullato.
    {% else %}
      This product is temporarily <strong>unable to be shipped</strong> to the <strong>UNITED STATES</strong> due to customs restrictions. As a result, the entire order containing it will be cancelled.
    {% endif %}
  </div>
{% endif %}
